class Solution {
  public int minDeletionSize(String[] strs) {
    int n = strs.length, m = strs[0].length(), ans = 0;
    boolean[] fixed = new boolean[n - 1];
    for (int c = 0; c < m; c++) {
      boolean bad = false;
      for (int r = 0; r < n - 1; r++)
        if (!fixed[r] && strs[r].charAt(c) > strs[r + 1].charAt(c)) {
          bad = true;
          break;
        }
      if (bad) {
        ans++;
        continue;
      }
      for (int r = 0; r < n - 1; r++)
        if (strs[r].charAt(c) < strs[r + 1].charAt(c)) fixed[r] = true;
    }
    return ans;
  }
}
